using System;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-a9cbe1a7db0243ecbdd7437bf8982a6e/build.binlog");

// Check all projects and their build results
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"Project: {p.Name} Succeeded={p.Succeeded}");
}

Console.WriteLine("\n--- All Errors ---");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    Console.WriteLine($"[{e.Code}] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Text}");
    Console.WriteLine($"  Project: {e.ProjectFile}");
    Console.WriteLine();
}

Console.WriteLine("--- Messages containing 'failed' or 'error' ---");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages)
{
    if (m.Text != null && (m.Text.Contains("failed", StringComparison.OrdinalIgnoreCase) || 
        m.Text.Contains("MSB3202", StringComparison.OrdinalIgnoreCase) ||
        m.Text.Contains("could not be built", StringComparison.OrdinalIgnoreCase)))
    {
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
    }
}
EOF
