using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-a9cbe1a7db0243ecbdd7437bf8982a6e/build.binlog");

// Check build result
Console.WriteLine($"Build succeeded: {build.Succeeded}");

// Look for any target that indicates project dependency failure
var items = build.FindChildrenRecursive<Item>();
foreach (var item in items)
{
    if (item.Text != null && item.Text.Contains("_ResolveProjectReferenceDependencies"))
        Console.WriteLine($"Item: {item.Text}");
}

// Check if Api project actually compiled 
var tasks = build.FindChildrenRecursive<Task>();
foreach (var t in tasks)
{
    if (t.Name == "Csc")
    {
        var parent = t.Parent;
        while (parent != null && !(parent is Project))
            parent = parent.Parent;
        if (parent is Project p)
            Console.WriteLine($"Csc ran in: {p.Name}");
    }
}
EOF
